// LabDesk validated engineering calculator.
// Accepted examples:
//   Ohm: V=12 V, R=4 ohm, find I
//   Power: V=12 V, I=2 A, find P
//   Convert 1011 binary to decimal

const raw = String($flow.input || $flow.question || '').trim();
if (!raw) return 'Please enter a calculation. Example: V=12 V, R=4 ohm, find I.';

const conversion = raw.match(/(?:convert\s+)?([+-]?[0-9A-Fa-f]+)\s*(binary|bin|decimal|dec|octal|oct|hexadecimal|hex)\s*(?:to|into)\s*(binary|bin|decimal|dec|octal|oct|hexadecimal|hex)/i);
if (conversion) {
  const bases={binary:2,bin:2,decimal:10,dec:10,octal:8,oct:8,hexadecimal:16,hex:16};
  const src=conversion[2].toLowerCase(), dst=conversion[3].toLowerCase();
  const base=bases[src], outBase=bases[dst];
  const token=conversion[1], negative=token.startsWith('-');
  const digits=token.replace(/^[+-]/,'').toUpperCase();
  if (!digits) return 'No digits were provided.';
  const allowed='0123456789ABCDEF'.slice(0,base);
  for (const ch of digits) if (!allowed.includes(ch)) return `Invalid digit "${ch}" for base ${base}.`;
  let value=0n;
  for (const ch of digits) value=value*BigInt(base)+BigInt(allowed.indexOf(ch));
  if (negative) value=-value;
  return `${token} (${src}) = ${value.toString(outBase).toUpperCase()} (${dst}).`;
}

const vals={};
const re=/\b([VIRP])\s*=\s*(-?\d+(?:\.\d+)?)\s*(mA|A|mV|V|kOhm|kohm|ohm|Ohm|Ω|W|mW)?/gi;
let m;
while ((m=re.exec(raw))!==null) {
  const key=m[1].toUpperCase(); let value=Number(m[2]); const unit=(m[3]||'').toLowerCase();
  if (!Number.isFinite(value)) return 'Invalid numeric value.';
  if (key==='V' && unit==='mv') value/=1000;
  if (key==='I' && unit==='ma') value/=1000;
  if (key==='R' && (unit==='kohm'||unit==='kohm')) value*=1000;
  if (key==='P' && unit==='mw') value/=1000;
  vals[key]=value;
}
const targetMatch=raw.match(/(?:find|calculate|solve\s+for)\s+(voltage|current|resistance|power|v|i|r|p)\b/i);
const aliases={voltage:'V',current:'I',resistance:'R',power:'P'};
const target=targetMatch ? (aliases[targetMatch[1].toLowerCase()]||targetMatch[1].toUpperCase()) : '';
if (!target) return 'I could not identify the unknown. Specify “find V”, “find I”, “find R”, or “find P”.';
for (const k of Object.keys(vals)) if (vals[k]<0) return `${k} cannot be negative for this basic DC calculator.`;
if (vals.R===0) return 'Resistance must be greater than zero.';
const known=Object.keys(vals).filter(k=>k!==target);
if (known.length<2) return 'Please provide two known quantities. Example: V=12 V, R=4 ohm, find I.';
let result, formula;
const V=vals.V,I=vals.I,R=vals.R,P=vals.P;
if (target==='I' && V!==undefined && R!==undefined) { result=V/R; formula='I = V / R'; }
else if (target==='V' && I!==undefined && R!==undefined) { result=I*R; formula='V = I × R'; }
else if (target==='R' && V!==undefined && I!==undefined) { if(I===0) return 'Current must be non-zero to calculate resistance from V/I.'; result=V/I; formula='R = V / I'; }
else if (target==='P' && V!==undefined && I!==undefined) { result=V*I; formula='P = V × I'; }
else if (target==='P' && V!==undefined && R!==undefined) { result=V*V/R; formula='P = V² / R'; }
else if (target==='P' && I!==undefined && R!==undefined) { result=I*I*R; formula='P = I² × R'; }
else if (target==='I' && P!==undefined && V!==undefined) { if(V===0) return 'Voltage must be non-zero to calculate current from P/V.'; result=P/V; formula='I = P / V'; }
else if (target==='V' && P!==undefined && I!==undefined) { if(I===0) return 'Current must be non-zero to calculate voltage from P/I.'; result=P/I; formula='V = P / I'; }
else if (target==='R' && P!==undefined && I!==undefined) { if(I===0) return 'Current must be non-zero to calculate resistance from P/I².'; result=P/(I*I); formula='R = P / I²'; }
else return `The supplied values do not determine ${target}. Use two compatible known values from V, I, R, P.`;
if (!Number.isFinite(result)) return 'The calculation produced an invalid result. Check the input values and units.';
const unit={V:'V',I:'A',R:'Ω',P:'W'}[target];
return `Validated calculation\nGiven: ${Object.entries(vals).map(([k,v])=>`${k}=${v}`).join(', ')}\nFormula: ${formula}\n${target} = ${Number(result.toPrecision(8))} ${unit}\nCheck the units before using this result in a physical circuit.`;
